const escape=value=>value.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const rules=messages.filter(([key])=>key.includes('{')).map(row=>{const slots=[];let pattern='',start=0;for(const match of row[0].matchAll(/\{(\d+)\}/g)){pattern+=escape(row[0].slice(start,match.index))+'(.+?)';slots.push(Number(match[1]));start=match.index+match[0].length;}pattern+=escape(row[0].slice(start));return {row,slots,regex:new RegExp('^'+pattern+'$')};}).sort((a,b)=>b.row[0].replace(/\{\d+\}/g,'').length-a.row[0].replace(/\{\d+\}/g,'').length);
const exact=new Map(messages.filter(([key])=>!key.includes('{')).map(row=>[row[0],row]));
export function translate(value,lang=language,depth=0){
 if(lang==='ko'||!languages[lang]||depth>8)return value;
 const index=lang==='en'?1:2,found=exact.get(value);if(found)return found[index];
 const trimmed=value.trim();if(trimmed!==value&&trimmed){const translated=translate(trimmed,lang,depth+1);if(translated!==trimmed)return value.slice(0,value.indexOf(trimmed))+translated+value.slice(value.indexOf(trimmed)+trimmed.length);}
 for(const {row,slots,regex} of rules){const match=value.match(regex);if(match){const args={};slots.forEach((slot,i)=>args[slot]=translate(match[i+1],lang,depth+1));return row[index].replace(/\{(\d+)\}/g,(_,slot)=>args[slot]);}}
 return value;
}
export function placeLabel(place,lang=language){
 const label=place?.label||'';if(lang==='ko'||place?.source==='maptiler'||!/[가-힣]/.test(label))return translate(label,lang);
 const terms=Array.isArray(place.terms)?place.terms:[];
 const original=terms.find(term=>!/[가-힣]/.test(term)&&/[\p{Script=Han}]/u.test(term));
 if(lang==='yue'&&original)return original;
 const parts=label.split(' · '),english=parts.find(part=>!/[가-힣]/.test(part)&&/[A-Za-z]/.test(part));
 return english||translate(label,lang);
}
export function installLanguageUI(doc=document){
 const records=new WeakMap(),attributes=['placeholder','aria-label','title','content'];
 const localized=(node,key,value,write)=>{let fields=records.get(node);if(!fields){fields=new Map();records.set(node,fields);}const old=fields.get(key),source=old&&value===old.output?old.source:value;const output=translate(source);fields.set(key,{source,output});if(value!==output)write(output);};
 const visit=root=>{
  if(root.nodeType===3){if(root.parentElement?.closest('script,style,select#language'))return;localized(root,'text',root.nodeValue,value=>{root.nodeValue=value;});return;}
  if(root.nodeType!==1&&root.nodeType!==9)return;
  if(root.nodeType===1){if(root.matches('script,style'))return;for(const name of attributes)if(root.hasAttribute(name))localized(root,name,root.getAttribute(name),value=>root.setAttribute(name,value));}
  if(root.nodeType===1&&root.matches('select#language'))return;
  for(const child of root.childNodes)visit(child);
 };
 const selector=doc.getElementById('language');
 const apply=()=>{doc.documentElement.lang=languages[language].tag;selector.value=language;visit(doc);};
 const observer=new MutationObserver(changes=>{for(const change of changes){if(change.type==='childList')for(const node of change.addedNodes)visit(node);else visit(change.target);}});
 observer.observe(doc.documentElement,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:attributes});
 selector.addEventListener('change',()=>{setLanguage(selector.value);apply();doc.dispatchEvent(new CustomEvent('languagechange',{detail:{language}}));});apply();
 return {apply,disconnect:()=>observer.disconnect()};
}
